package org.jsoup.helper;

import java.net.URI;
import java.util.HashMap;
import java.util.Map;

public class UrlBuilderTest {

    @Test
    public void newUrlBuilder() {
        assertTrue(new UrlBuilder(null).build().equals(null));
    }

    @Test
    public void appendKeyVal_NoParameters_ThrowsUnsupportedEncodingException() throws UnsupportedEncodingException {
        // Create a new UrlBuilder instance
        UrlBuilder builder = new UrlBuilder(null);

        try {
            // Try to append key-value pair with no parameters
            builder.appendKeyVal((String)null, (String)null); // Java 8 
            fail("Expected UnsupportedEncodingException");
        } catch (UnsupportedEncodingException e) {
            // Expected
        }
    }

    @Test
    public void appendKeyVal_WithParameters_BuildsCorrectly() throws UnsupportedEncodingException {
        Map<String, String> param = new HashMap<>();
        param.put("key", "value");

        // Create a string representing key-value pair with parameters
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, String> entry : param.entrySet()) {
            sb.append(entry.getKey()).append("=").append(URLEncoder.encode(entry.getValue(), "UTF-8")).append("&");
        }
        String encodedKey = sb.toString().trimEnd();

        // Create a new UrlBuilder instance
        UrlBuilder builder = new UrlBuilder(null);

        // Append key-value pair with parameters to the UrlBuilder
        builder.appendKeyVal(encodedKey);

        // Build the URL from the UrlBuilder
        URI uri = new URI(builder.build());

        assertEquals(URI.create("key=value").toASCIIString(), uri.toString());
    }

    @Test
    public void build_WorksWithEmptyUrl() {
        UrlBuilder builder = new UrlBuilder(null);
        assertEquals(null, builder.build());
    }

    @Test
    public void build_WorksWithValidUrl() throws MalformedURLException {
        String url = "http://example.com";

        // Create a new UrlBuilder instance with valid URL
        UrlBuilder builder = new UrlBuilder(new java.net.URL(url));

        // Build the URL from the UrlBuilder
        URI uri = new URI(builder.build());

        assertEquals(URI.create("http://example.com").toASCIIString(), uri.toString());
    }

}

public class UrlBuilder {

    private String url;

    public UrlBuilder() {
    }

    public UrlBuilder(String url) {
        this.url = url;
    }

    public void appendKeyVal(String encodedKey) {
        if (encodedKey != null && !encodedKey.isEmpty()) {
            // Check that you actually want to add the query parameter
            this.url += "?" + encodedKey;
        }
    }

    public String build() {
        return url;
    }

}
